<?php

declare(strict_types=1);

/*
 * FrankenPHP Worker Mode Entry Point for TYPO3
 *
 * This file is the entry point for FrankenPHP worker mode.
 * It is auto-generated by the ochorocho/frankenphp Composer installer.
 * DO NOT EDIT THIS FILE.
 */

use Ochorocho\FrankenPhp\Profiler\ProfileLog;
use Ochorocho\FrankenPhp\Profiler\RequestProfile;
use Ochorocho\FrankenPhp\Worker\RuntimeCacheInventory;
use Ochorocho\FrankenPhp\Worker\WorkerLifetime;
use Ochorocho\FrankenPhp\Worker\WorkerRequestCycle;
use Ochorocho\FrankenPhp\Worker\WorkerStateResetter;
use TYPO3\CMS\Core\Core\Bootstrap;
use TYPO3\CMS\Core\Core\SystemEnvironmentBuilder;
use TYPO3\CMS\Core\Http\Application as HttpApplication;
use TYPO3\CMS\Install\Http\Application as InstallApplication;

ignore_user_abort(true);

// Marker used by Ochorocho\FrankenPhp\EventListener\AddFrankenPhpModeToSystemInformation
// to distinguish worker-mode requests (this file) from per-request /index.php
// execution (the install-tool recovery path). Set once per worker process and
// remains true for every request the worker handles; not visible to /index.php
// since that runs in a fresh PHP interpreter.
const TYPO3_FRANKENPHP_WORKER_MODE = true;

// BOOT PHASE — runs once per worker process.
$classLoader = require __DIR__ . '/../../../../../../vendor/autoload.php';
SystemEnvironmentBuilder::run();

// Mirror public/index.php — Bootstrap needs to know whether to bring up the
// install tool. In worker mode the actual request URLs aren't known yet, so
// we pass false here and rely on the container probing below to fall back to
// InstallApplication when HttpApplication isn't available (e.g. settings.php
// missing → FailsafeContainer).
$container = Bootstrap::init($classLoader, false);

// FailsafeContainer (install-tool / no settings.php) doesn't load extension
// Services.yaml, so WorkerStateResetter is absent. Degrade gracefully —
// the install tool has no long-lived singleton state that matters.
$resetter = $container->has(WorkerStateResetter::class)
    ? $container->get(WorkerStateResetter::class)
    : null;
$snapshot = $resetter?->capture($container);

// Pick the application. In a fully-installed system HttpApplication is
// available. If only the install tool is available (settings.php missing),
// fall back to that. If neither is available the worker still has to keep
// running so FrankenPHP doesn't trip max_consecutive_failures — emit 500s
// from the request loop instead of fataling here.
//
// Only the class is decided here. The instance is fetched per request:
// the Application holds the RequestHandler / middleware chain by reference,
// and those are discarded by the resetter, so a boot-time instance would
// keep stale references.
$applicationClass = null;
if ($container->has(HttpApplication::class)) {
    $applicationClass = HttpApplication::class;
} elseif ($container->has(InstallApplication::class)) {
    $applicationClass = InstallApplication::class;
}

$workerLogFile = \TYPO3\CMS\Core\Core\Environment::getVarPath() . '/log/frankenphp-worker.log';
@mkdir(dirname($workerLogFile), 0775, true);
$isDevelopment = \TYPO3\CMS\Core\Core\Environment::getContext()->isDevelopment();

// Reset strategy. With frankenphp_finish_request() the structural reset runs
// after the response has left the worker; otherwise (or after a failed
// post-response phase) it runs inline at the start of the next request.
$finishRequest = null;
if (function_exists('frankenphp_finish_request')) {
    $finishRequest = static function (): void {
        \frankenphp_finish_request();
    };
} elseif (function_exists('fastcgi_finish_request')) {
    $finishRequest = static function (): void {
        \fastcgi_finish_request();
    };
}
// Development aid: FRANKENPHP_RUNTIME_CACHE_INVENTORY=1 logs what each
// request left in cache.runtime (`frankenphp:audit --runtime-cache` reads it).
$inventory = null;
if ($isDevelopment && ($_SERVER[RuntimeCacheInventory::ENV_FLAG] ?? getenv(RuntimeCacheInventory::ENV_FLAG)) === '1') {
    $inventory = new RuntimeCacheInventory(dirname($workerLogFile) . '/' . RuntimeCacheInventory::LOG_BASENAME);
}
// Development aid: FRANKENPHP_PROFILE=1 records where each request spends its
// time (Documentation/Profiling.md). The collector is a pinned service that
// exists in Development containers only; production never sees it.
$profile = null;
$profileLog = null;
if ($isDevelopment && $container->has(RequestProfile::class)) {
    $profile = $container->get(RequestProfile::class);
    $profile->enable(($_SERVER[RequestProfile::ENV_FLAG] ?? getenv(RequestProfile::ENV_FLAG)) === '1');
    $profileLog = new ProfileLog(dirname($workerLogFile) . '/' . RequestProfile::LOG_BASENAME);
}
$cycle = null;
if ($resetter !== null && $snapshot !== null && $applicationClass !== null) {
    $cycle = new WorkerRequestCycle(
        $resetter,
        $snapshot,
        $container,
        $applicationClass,
        $finishRequest,
        $inventory !== null ? static function () use ($inventory, $container): void {
            $inventory->record($container);
        } : null,
    );
}

// REQUEST HANDLER — runs per incoming request.
$handler = static function () use ($container, $cycle, $applicationClass, $workerLogFile, $isDevelopment, $profile, $profileLog): void {
    $requestStart = hrtime(true);
    // AbstractApplication::sendResponse() may clear all output buffers when
    // emitting SelfEmittableStreamInterface (file downloads). Without a fresh
    // ob_start, subsequent requests would have no output buffering.
    ob_start();

    try {
        if ($applicationClass === null) {
            throw new \RuntimeException(
                'TYPO3 worker boot incomplete: neither HttpApplication nor InstallApplication is '
                . 'available in the container. Check config/system/settings.php and var/cache/.'
            );
        }
        if ($cycle === null) {
            // FailsafeContainer: no resetter, nothing to reset.
            $container->get($applicationClass)->run();
        } else {
            $application = $cycle->begin();
            $profile?->beginRequest($requestStart);
            if ($isDevelopment) {
                // Tuning aids. Discarded: service instances the previous
                // request left behind (should stabilise after warm-up; growth
                // means a leak). Reset-Us: reset time inside this request's
                // latency. Post-Reset-Us: reset time spent after the previous
                // response, invisible to clients. Reset-Mode: "post" when the
                // previous response's post phase prepared this request.
                header('X-FrankenPHP-Discarded: ' . $cycle->discarded());
                header('X-FrankenPHP-Reset-Us: ' . $cycle->resetMicroseconds());
                header('X-FrankenPHP-Post-Reset-Us: ' . $cycle->postResetMicroseconds());
                header('X-FrankenPHP-Reset-Mode: ' . $cycle->mode());
            }
            $application->run();
        }
    } catch (\Throwable $e) {
        // One-line summary always goes through PHP's normal log channel —
        // syslog / stderr / wherever error_log is configured to land.
        $requestLine = sprintf('%s %s', $_SERVER['REQUEST_METHOD'] ?? '?', $_SERVER['REQUEST_URI'] ?? '?');
        $traceText = sprintf(
            "[%s] %s\n  %s: %s\n  at %s:%d\n%s\n\n",
            date('c'),
            $requestLine,
            $e::class,
            $e->getMessage(),
            $e->getFile(),
            $e->getLine(),
            $e->getTraceAsString()
        );
        error_log('TYPO3 Worker Error: ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
        // Full stack trace dumped to var/log/frankenphp-worker.log only in
        // development. In production this file would grow unbounded under
        // any sustained burst of exceptions; one-line error_log() above is
        // enough to flag the incident, and the developer can re-enable this
        // for ad-hoc debugging by editing TYPO3_CONTEXT in .env.
        if ($isDevelopment) {
            @file_put_contents($workerLogFile, $traceText, FILE_APPEND | LOCK_EX);
        }

        // Delegate to TYPO3's registered exception handler so client errors
        // (AbstractClientErrorException — rate limit, forbidden, not found)
        // render their intended 4xx page instead of a flat 500. Bootstrap
        // registers the handler via set_exception_handler() so we discover
        // it through the null-set round-trip.
        $registeredHandler = set_exception_handler(null);
        if ($registeredHandler !== null) {
            set_exception_handler($registeredHandler);
            try {
                $registeredHandler($e);
            } catch (\Throwable $nested) {
                @file_put_contents(
                    $workerLogFile,
                    "    registered exception handler also threw: " . $nested->getMessage() . "\n\n",
                    FILE_APPEND | LOCK_EX
                );
                if (!headers_sent()) {
                    header('HTTP/1.1 500 Internal Server Error');
                    header('Content-Type: text/plain');
                }
                echo $isDevelopment ? $traceText : 'Internal Server Error';
            }
        } else {
            // No TYPO3 handler available — our own last-resort response.
            if (!headers_sent()) {
                header('HTTP/1.1 500 Internal Server Error');
                header('Content-Type: text/plain');
            }
            echo $isDevelopment ? $traceText : 'Internal Server Error';
        }
    } finally {
        // PHP-FPM auto-commits sessions to disk at request shutdown;
        // FrankenPHP workers do not. Without this call, anything written to
        // $_SESSION during the request (e.g. the install tool's
        // BackendModuleController setting up the Typo3InstallTool session
        // before redirecting to its iframe AJAX endpoint) never lands on
        // disk before the browser's follow-up request reads it — surfacing
        // as "The Install Tool session expired" 403s across Maintenance /
        // Settings / Upgrade.
        if (session_status() === PHP_SESSION_ACTIVE) {
            session_write_close();
        }
        while (ob_get_level()) {
            ob_end_flush();
        }
        // Response complete: send it, then reset for the next request while
        // no client waits. finish() never throws; a failure makes the next
        // begin() fall back to the inline reset.
        if ($cycle !== null) {
            $cycle->finish();
            if ($profile?->isEnabled() && $profileLog !== null) {
                $profileLog->append($profile->toRecord(hrtime(true) - $requestStart, [
                    'reset_us' => $cycle->resetMicroseconds(),
                    'post_reset_us' => $cycle->postResetMicroseconds(),
                    'mode' => $cycle->mode(),
                    'discarded' => $cycle->discarded(),
                ]));
            }
            $failure = $cycle->lastFailure();
            if ($failure !== null) {
                error_log('TYPO3 Worker: post-response reset failed, next request resets inline: '
                    . $failure->getMessage() . ' in ' . $failure->getFile() . ':' . $failure->getLine());
            }
            if ($isDevelopment && ($failure !== null || $cycle->strayOutput() !== '')) {
                @file_put_contents($workerLogFile, sprintf(
                    "[%s] post-response phase\n%s%s\n",
                    date('c'),
                    $failure !== null ? $failure . "\n" : '',
                    $cycle->strayOutput() !== '' ? 'Output after the response: ' . $cycle->strayOutput() : ''
                ), FILE_APPEND);
            }
        }
    }
};

// WORKER LOOP — bounded by MAX_REQUESTS (with a per-worker jitter so the pool
// does not recycle in lockstep) and MAX_MEMORY_MB, both mitigating memory
// leaks in third-party libraries never designed for a long-running process.
$lifetime = WorkerLifetime::fromEnvironment($_SERVER, memory_get_usage(true));
if ($lifetime->warning !== null) {
    error_log('TYPO3 Worker: ' . $lifetime->warning);
}
$handledRequests = 0;
while ($lifetime->allowsAnotherRequest($handledRequests, memory_get_usage(true))) {
    $keepRunning = \frankenphp_handle_request($handler);
    $handledRequests++;
    gc_collect_cycles();
    if (!$keepRunning) {
        break;
    }
}
